```python
async def request_validation_exception_handler(
    request: Request, exc: RequestValidationError
) -> JSONResponse:
    # Ensure the response can serialize Decimals by converting them to floats
    detail = []
    for error in exc.errors():
        # Convert Decimal values to float if they exist in the error context
        if 'ctx' in error and 'limit_value' in error['ctx']:
            error['ctx']['limit_value'] = float(error['ctx']['limit_value'])
        detail.append(error)

    return JSONResponse(
        status_code=HTTP_422_UNPROCESSABLE_ENTITY, content={"detail": detail}
    )
```

